        for (int neighbor : adj[node])
        {
            inDegree[neighbor]--;

            // If all prerequisites of this task are completed,
            // add it to the queue
            if (inDegree[neighbor] == 0)
                q.push(neighbor);
        }
    }

    // If all tasks were processed, a valid topological
    // ordering exists and all tasks can be completed
    return completed == n;
}

